/// Rep max set, then 3 volume sets at 80% of what you hit. The first volume set is AMRAP.
/// The update script sets the volume weight right after the rep max set.
/// The progress script updates the variation's 1RM, so the next suggested rep max is closer.
// **Strength + volume, in giant sets.** Work up to today's rep max in small jumps. Every warm-up attempt is one giant set round with the 3 other exercises.
// Enter the weight you hit. The volume sets become 80% of it. First volume set: as many reps as possible.
// If the volume reps don't come, break them into smaller sets and get all the reps.
me5[1-9] / used: none / 1x5 (RM) @10 ?+, 1x10+ (80%) 70%, 2x10 (80%) 70% / 15s / update: custom() {~
  if (setIndex == 0) {
    var.w = roundWeight(weights[1] * 0.8)
    weights[2] = var.w
    weights[3] = var.w
    weights[4] = var.w
  }
  if (setIndex == 1 && completedReps[1] > 0) {
    var.w = roundWeight(completedWeights[1] * 0.8)
    weights[2] = var.w
    weights[3] = var.w
    weights[4] = var.w
  }
~} / progress: custom() {~
  if (completedReps[1] > 0) {
    rm1 = calculate1RM(completedWeights[1], completedReps[1])
  }
~}
me3[1-9] / used: none / 1x3 (RM) @10 ?+, 1x8+ (80%) 74%, 2x8 (80%) 74% / 15s / update: custom() { ...me5 } / progress: custom() { ...me5 }
me1[1-9] / used: none / 1x1 (RM) @10 ?+, 1x5+ (80%) 80%, 2x5 (80%) 80% / 15s / update: custom() { ...me5 } / progress: custom() { ...me5 }
// **Speed work.** One set of 3 every minute for 10 minutes. Competition grip and stance. Move the bar as fast as you can. Bands or chains if you have them.
de[1-10] / used: none / 10x3 / 50% 60s|0s auto
// **Assistance.** Skip it on days you're fried.
acc[1-9] / used: none / 3x10 / 60s / warmup: none / progress: dp(5lb, 10, 15)

// Light - it's here to keep you moving between deadlift attempts.
Goblet Squat[1-9] / 4x10 / 35lb 15s / warmup: none / progress: dp(5lb, 10, 15) / superset: giant
// ...me5
Deficit Deadlift / ...me3 / superset: giant
Ab Wheel[1-9] / 4x10 / 0lb 15s / warmup: none / superset: giant
Ball Slams[1-9] / 4x10 / 20lb 90s / warmup: none / superset: giant
// ...de
de: Squat[1-10] / ...de
// ...acc
Back Extension[1-9] / ...acc / 0lb
// ...acc
Shrug[1-9] / ...acc / 45lb
// **Optional conditioning.** 30s on, 30s off, 10 rounds.
Battle Ropes[1-9] / 10x1 / 30s|30s auto / warmup: none

// Add weight on a belt once 4x8 is easy.
Pull Up[1-9] / 4x5 / 0lb 15s / warmup: none / progress: dp(5lb, 5, 8) / superset: giant
// ...me5
Push Press, Barbell / ...me1 / superset: giant
Dragon Flag[1-9] / 4x5 / 0lb 15s / warmup: none / superset: giant
Battle Ropes[1-9] / 4x1 / 20s|90s / warmup: none / superset: giant
// ...de
de: Bench Press[1-10] / ...de
// ...acc
Lateral Raise[1-9] / ...acc / 15lb
// ...acc
Skullcrusher[1-9] / ...acc / 45lb
// **Optional conditioning.** 5 light thrusters every minute, 10 minutes.
Thruster[1-9] / 10x5 / 45lb 60s|0s auto / warmup: none

Romanian Deadlift, Barbell[1-9] / 4x12 / 95lb 15s / warmup: none / progress: dp(5lb, 12, 15) / superset: giant
// ...me5
Box Squat / ...me5 / superset: giant
Hanging Leg Raise[1-9] / 4x10 / 0lb 15s / warmup: none / superset: giant
Kettlebell Swing[1-9] / 4x12 / 35lb 90s / warmup: none / superset: giant
// ...de
de: Deadlift[1-10] / ...de
// ...acc
Bulgarian Split Squat[1-9] / ...acc / 25lb
// ...acc
Lying Leg Curl[1-9] / ...acc / 50lb
// **Optional conditioning.** 5 jump squats every minute, 10 minutes.
Jump Squat, Bodyweight[1-9] / 10x5 / 0lb 60s|0s auto / warmup: none

Bent Over Row[1-9] / 4x8 / 95lb 15s / warmup: none / progress: dp(5lb, 8, 12) / superset: giant
// ...me5
Bench Press Close Grip / ...me3 / superset: giant
Plank[1-9] / 4x1 / 30s|15s / warmup: none / superset: giant
Ball Slams[1-9] / 4x10 / 20lb 90s / warmup: none / superset: giant
// ...de
de: Overhead Press[1-10] / ...de
// ...acc
Face Pull[1-9] / ...acc / 30lb
// ...acc
Triceps Dip[1-9] / ...acc / 0lb
// **Optional conditioning.** 10 swings every minute, 10 minutes.
Kettlebell Swing[1-9] / 10x10 / 35lb 60s|0s auto / warmup: none

// **Max test.** Work up through the warm-ups, then go for a new 1RM. Enter the weight you lifted - it becomes your new 1RM. Rest 3-5 minutes between heavy attempts.
test[11-12] / used: none / 1x1 (Test) 100%+ / 300s / warmup: 1x5 40%, 1x3 60%, 1x2 75%, 1x1 85%, 1x1 92% / progress: custom() {~
  if (completedReps[1] >= 1) {
    rm1 = completedWeights[1]
  }
~}
// ...test
test: Deadlift / ...test
